import json, sys
data = json.load(sys.stdin)
# Group by headword_norm
groups = {}
for r in data:
    k = r['headword_norm']
    if k not in groups:
        groups[k] = []
    groups[k].append(r)
for k in sorted(groups.keys()):
    entries = groups[k]
    print(f'=== {k} ({len(entries)} entries) ===')
    for e in entries[:5]:
        print(f'  id={e[\"entry_id\"]} hw={e[\"headword\"]} root={e.get(\"root\")} pos={e.get(\"pos\")} src={e[\"source_type\"]}')
        defn = (e.get('definitions_text') or '')[:150]
        if defn: print(f'    def: {defn}')
        tr = e.get('translation_en')
        if tr: print(f'    en: {tr}')
    if len(entries) > 5:
        print(f'  ... and {len(entries)-5} more')
"
